examples.code:
- uses: docker/login-action@v3
  with:
    registry: ghcr.io
    username: ${{ github.actor }}
    password: ${{ secrets.GITHUB_TOKEN }}
- uses: docker/build-push-action@v6
  with:
    push: true
    tags: ghcr.io/${{ github.repository }}:${{ github.sha }}

# Builds an image with no Docker daemon and no privileged mode
/kaniko/executor --dockerfile=Dockerfile \
  --destination=ghcr.io/eknatha/myapp:${CI_COMMIT_SHA}

{
  "log-driver": "json-file",
  "log-opts": { "max-size": "10m", "max-file": "3" }
}

# A Deployment says 'always keep 3 healthy replicas';
# the controller recreates pods that die or land on failed nodes.
spec:
  replicas: 3
  strategy: { type: RollingUpdate }

services:
  app:      { image: myapp }
  logagent: { image: fluent/fluent-bit }
# these are separate containers reached by name, not via shared localhost
